package in.jharkhand.civic.controller;
import in.jharkhand.civic.service.ProblemService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.Authentication; import java.util.*;
@RestController @RequestMapping("/api/routing") public class RoutingController {private final ProblemService p;public RoutingController(ProblemService p){this.p=p;}@PostMapping("/{id}/approve") @PreAuthorize("hasRole('ADMIN')") Map<String,Object> approve(@PathVariable String id,Authentication a){return p.approveRouting(id,a.getName(),"ADMIN");}@PostMapping("/{id}/reject") @PreAuthorize("hasRole('ADMIN')") Map<String,Object> reject(@PathVariable String id){return Map.of("routeId",id,"approved",false,"message","Routing rejected for human review");}}
